// --- Brick collision (pure, tested primitive) ------------------------------

// Resolves every ball/brick overlap in the state, exactly once per face hit:
//
// - the axis with the SMALLER penetration is the face that was hit — flip `vy`
//   on a top/bottom hit, `vx` on a side hit, leave the other component alone;
// - EQUAL penetrations mean a diagonal (corner) hit — flip both components;
// - the ball is pushed back out of the rectangle (to the exact edge) so it
//   cannot still overlap on the next frame and re-flip forever (sticky bounce);
// - the grid gap is 8 px and the ball 14 px across, so every seam overlaps TWO
//   bricks in the same pass — the bounce is decided from the single smallest
//   penetration across ALL overlapped bricks and the push-out clears them all,
//   so `vy = -vy` can never be applied twice and cancel out.
//
// Bricks that are touched are destroyed and scored, exactly like the old
// render-loop code did — the collision logic simply no longer lives in
// `frame()` (debt #2).
//
// A second resolution pass (max 4) catches the rare overlap left behind by a
// corner between two bricks: pushing out on one axis can leave the ball inside
// a neighbour, which then contributes its own bounce — a real corner response.
function resolveBricks(state) {
  const { ball, bricks } = state;

  for (let pass = 0; pass < 4; pass++) {
    let best = null; // { penX, penY, dxLeft, dxRight, dyTop, dyBottom }

    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;

      // Destroy + score every brick the ball touches in this pass.
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // Penetration along each axis (how far the ball's edge is past the
      // brick's edge on the side it entered from).
      const dxLeft = ball.x + ball.r - brick.x;
      const dxRight = brick.x + brick.w - (ball.x - ball.r);
      const dyTop = ball.y + ball.r - brick.y;
      const dyBottom = brick.y + brick.h - (ball.y - ball.r);
      const penX = Math.min(dxLeft, dxRight);
      const penY = Math.min(dyTop, dyBottom);
      const m = Math.min(penX, penY);
      if (!best || m < best.m) best = { m, penX, penY, dxLeft, dxRight, dyTop, dyBottom };
    }

    if (!best) return;

    const { penX, penY, dxLeft, dxRight, dyTop, dyBottom } = best;

    // Side hit: flip vx, push out sideways. Which side is hit is read from
    // which edge the ball crossed (mirrors the wall bounces in step()).
    if (penX < penY) {
      if (dxLeft <= dxRight) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = brickLeftEdge - ball.r;
      } else {
        ball.vx = Math.abs(ball.vx);
        ball.x = brickRightEdge + ball.r;
      }
    }
    // Top/bottom hit: flip vy, push out vertically.
    else if (penY < penX) {
      if (dyTop <= dyBottom) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = brickTopEdge - ball.r;
      } else {
        ball.vy = Math.abs(ball.vy);
        ball.y = brickBottomEdge + ball.r;
      }
    }
    // Corner: equal penetrations — flip both, push out on both axes.
    else {
      if (dxLeft <= dxRight) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = brickLeftEdge - ball.r;
      } else {
        ball.vx = Math.abs(ball.vx);
        ball.x = brickRightEdge + ball.r;
      }
      if (dyTop <= dyBottom) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = brickTopEdge - ball.r;
      } else {
        ball.vy = Math.abs(ball.vy);
        ball.y = brickBottomEdge + ball.r;
      }
    }
  }
}

