let best = null; // { m, penX, penY, left, right, top, bottom }

for (const brick of bricks) {
  if (!brick.alive || !collides(ball, brick)) continue;

  // Destroy + score every brick the ball touches in this pass.
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Penetration along each axis (how far the ball's edge is past the
  // brick's edge on the side it entered from).
  const dxLeft = ball.x + ball.r - brick.x;
  const dxRight = brick.x + brick.w - (ball.x - ball.r);
  const dyTop = ball.y + ball.r - brick.y;
  const dyBottom = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(dxLeft, dxRight);
  const penY = Math.min(dyTop, dyBottom);
  const m = Math.min(penX, penY);
  if (!best || m < best.m) {
    best = {
      m,
      penX,
      penY,
      dxLeft,
      dxRight,
      dyTop,
      dyBottom,
      left: brick.x,
      right: brick.x + brick.w,
      top: brick.y,
      bottom: brick.y + brick.h,
    };
  }
}

if (!best) return;

const { penX, penY, dxLeft, dxRight, dyTop, dyBottom, left, right, top, bottom } = best;

// Side hit: flip vx, push out sideways. Which side is hit is read from
// which edge the ball crossed (mirrors the wall bounces in step()).
if (penX < penY) {
  if (dxLeft <= dxRight) {
    ball.vx = -Math.abs(ball.vx);
    ball.x = left - ball.r;
  } else {
    ball.vx = Math.abs(ball.vx);
    ball.x = right + ball.r;
  }
}
// Top/bottom hit: flip vy, push out vertically.
else if (penY < penX) {
  if (dyTop <= dyBottom) {
    ball.vy = -Math.abs(ball.vy);
    ball.y = top - ball.r;
  } else {
    ball.vy = Math.abs(ball.vy);
    ball.y = bottom + ball.r;
  }
}
// Corner: equal penetrations — flip both, push out on both axes.
