// --- Brick collision (pure, tested primitive) ------------------------------

// Resolves every ball/brick overlap in the state, exactly once per face hit:
//
// - the axis with the SMALLER penetration is the face that was hit — flip `vy`
//   on a top/bottom hit, `vx` on a side hit, leave the other component alone;
// - EQUAL penetrations mean a diagonal (corner) hit — flip both components;
// - the ball is pushed back out of the rectangle (to the exact edge) so it
//   cannot still overlap on the next frame and re-flip forever (sticky bounce);
// - the grid gap is 8 px and the ball 14 px across, so every seam overlaps TWO
//   bricks in the same pass — the bounce is decided from the single smallest
//   penetration across ALL overlapped bricks and the push-out clears them all,
//   so `vy = -vy` can never be applied twice and cancel out.
//
// Bricks that are touched are destroyed and scored, exactly like the old
// render-loop code did — the collision logic simply no longer lives in
// `frame()` (debt #2).
//
// A second resolution pass (max 4) catches the rare overlap left behind by a
// corner between two bricks: pushing out on one axis can leave the ball inside
// a neighbour, which then contributes its own bounce — a real corner response.
function resolveBricks(state) {
  const { ball, bricks } = state;

  for (let pass = 0; pass < 4; pass++) {
    let best = null; // { m, penX, penY, left, right, top, bottom }

    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;

      // Destroy + score every brick the ball touches in this pass.
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // Penetration along each axis (how far the ball's edge is past the
      // brick's edge on the side it entered from).
      const dxLeft = ball.x + ball.r - brick.x;
      const dxRight = brick.x + brick.w - (ball.x - ball.r);
      const dyTop = ball.y + ball.r - brick.y;
      const dyBottom = brick.y + brick.h - (ball.y - ball.r);
      const penX = Math.min(dxLeft, dxRight);
      const penY = Math.min(dyTop, dyBottom);
      const m = Math.min(penX, penY);
      if (!best || m < best.m) {
        best = {
          m,
          penX,
          penY,
          dxLeft,
          dxRight,
          dyTop,
          dyBottom,
          left: brick.x,
          right: brick.x + brick.w,
          top: brick.y,
          bottom: brick.y + brick.h,
        };
      }
    }

    if (!best) return;

    const { penX, penY, dxLeft, dxRight, dyTop, dyBottom, left, right, top, bottom } = best;

    // Side hit: flip vx, push out sideways. Which side is hit is read from
    // which edge the ball crossed (mirrors the wall bounces in step()).
    if (penX < penY) {
      if (dxLeft <= dxRight) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = left - ball.r;
      } else {
        ball.vx = Math.abs(ball.vx);
        ball.x = right + ball.r;
      }
    }
    // Top/bottom hit: flip vy, push out vertically.
    else if (penY < penX) {
      if (dyTop <= dyBottom) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = top - ball.r;
      } else {
        ball.vy = Math.abs(ball.vy);
        ball.y = bottom + ball.r;
      }
    }
    // Corner: equal penetrations — flip both, push out on both axes.
    else {
      if (dxLeft <= dxRight) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = left - ball.r;
      } else {
        ball.vx = Math.abs(ball.vx);
        ball.x = right + ball.r;
      }
      if (dyTop <= dyBottom) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = top - ball.r;
      } else {
        ball.vy = Math.abs(ball.vy);
        ball.y = bottom + ball.r;
      }
    }
  }
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. The move is sub-stepped (MAX_MOVE) so
// a fast ball cannot tunnel through a brick, and brick collisions are resolved
// by resolveBricks() after each increment.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const sub = Math.max(1, Math.ceil(distance / MAX_MOVE));
  const h = dt / sub;

  for (let i = 0; i < sub; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Bricks: bounce + break + score (see resolveBricks).
    resolveBricks(state);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM): pure drawing, no game logic --------------------------

// Main render loop. Purely visual: every bounce (walls, paddle, bricks) and
// every score update happens in step()/resolveBricks() before this runs.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only — collisions are resolved in step().
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

